/**
 * Tự động chuẩn hóa dữ liệu từ vựng của 18 bài học với ID duy nhất và giọng phát âm riêng `tts:<hiragana>`
 */
export const MARUGOTO_VOCAB_SEED: Record<number, VocabularyItem[]> =
  Object.fromEntries(
    Object.entries(RAW_VOCAB_BY_LESSON).map(([lessonKey, items]) => {
      const lessonId = Number(lessonKey);
      const mapped: VocabularyItem[] = items.map((item, idx) => ({
        id: lessonId * 1000 + idx + 1,
        lesson_id: lessonId,
        kanji: item.kanji,
        hiragana: item.hiragana,
        romaji: item.romaji,
        meaning_vn: item.meaning_vn,
        audio_url: `tts:${item.hiragana}`,
        example_jp: item.example_jp,
        example_vn: item.example_vn,
      }));
      return [lessonId, mapped];
    })
  );

